notes:
/* EVERY DOT IS A PILL WITH TWO EDGES. The current step is
   the dot whose slot is wide; changing step changes two slot
   widths and every edge eases to its new place. */
const slot = (i) => (i === step ? 36 : 8);
edge.x = mix(from, to, easeOut(t / 520));   /* leaves at speed: no stall after a full bar */

/* THE WAKE. The dots the bar crossed stand up and settle in
   the order it crossed them, and the landing bar answers last.
   Wake is how far back from the landing it reaches; at 0 only
   the dot beside it moves and the landing gives a squash. */
const reach = 1 + round(wake * 7);
const self  = mix(-0.7, 0.3, wake);           /* squash .. lift */
.spl-dot { transform: scaleY(1 + sin(PI * u) * 0.34 * share); }
